package main

import "sort"

func TopKWords(text string, k int) []string {
	if k <= 0 {
		return []string{}
	}

	counts := map[string]int{}
	n := len(text)

	for i := 0; i < n; {
		c := text[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
			j := i
			for j < n {
				d := text[j]
				if (d >= 'a' && d <= 'z') || (d >= 'A' && d <= 'Z') {
					j++
				} else {
					break
				}
			}

			wordBytes := make([]byte, j-i)
			for idx := i; idx < j; idx++ {
				b := text[idx]
				if b >= 'A' && b <= 'Z' {
					b += 'a' - 'A'
				}
				wordBytes[idx-i] = b
			}

			counts[string(wordBytes)]++
			i = j
		} else {
			i++
		}
	}

	words := make([]string, 0, len(counts))
	for w := range counts {
		words = append(words, w)
	}

	sort.Slice(words, func(a, b int) bool {
		wa, wb := words[a], words[b]
		if counts[wa] != counts[wb] {
			return counts[wa] > counts[wb]
		}
		return wa < wb
	})

	if len(words) > k {
		words = words[:k]
	}
	return words
}
