fn compress(s: &str) -> String {
    let mut out = String::new();
    let mut iter = s.chars();
    while let Some(ch) = iter.next() {
        let mut count = 1usize;
        for next in iter.by_ref() {
            if next == ch {
                count += 1;
            } else {
                // cannot push back; handle via peekable instead
                unreachable!()
            }
        }
        unreachable!()
    }
    out
}
