fn eval_rpn(tokens: &[&str]) -> Option<i64> {
    let mut stack = Vec::new();
    for &tok in tokens {
        match tok {
            "+" => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                stack.push(a.checked_add(b)?);
            }
            "-" => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                stack.push(a.checked_sub(b)?);
            }
            "*" => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                stack.push(a.checked_mul(b)?);
            }
            "/" => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                if b == 0 {
                    return None;
                }
                stack.push(a.checked_div(b)?);
            }
            _ => {
                stack.push(tok.parse::<i64>().ok()?);
            }
        }
    }
    if stack.len() == 1 {
        Some(stack[0])
    } else {
        None
    }
}
